sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mode;
uniform float amzp_cx;
uniform float amzp_cy;
uniform float amzp_amp;
uniform float amzp_wl;
uniform float amzp_speed;
uniform float amzp_phase;
uniform float amzp_damp;
uniform float amzp_radius;
uniform float amzp_aspect;
uniform float amzp_dropTime;
uniform float amzp_dropRings;
uniform float amzp_dropFade;
uniform float amzp_light;
uniform float amzp_shade;
uniform float amzp_lAngle;
layout(color) uniform half4 amzp_lColor;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float wave(float d) {
        float L = max(amzp_wl, 2.0);
        float M = min(layer.x, layer.y);
        float env = exp(-amzp_damp * d / max(M, 1.0) * 2.0);
        if (amzp_radius > 0.0) env *= 1.0 - smoothstep(amzp_radius * M * 0.8, amzp_radius * M, d);
        if (int(amzp_mode) == 0) {
            return sin(6.2831853 * (d / L - time * amzp_speed) + radians(amzp_phase)) * env;
        }
        float t = time - amzp_dropTime;
        if (t < 0.0) return 0.0;
        float v = L * max(abs(amzp_speed), 0.01);
        float front = t * v;
        float tail = front - max(amzp_dropRings, 0.5) * L;
        float x = d;
        if (x > front || x < tail) return 0.0;
        float w = smoothstep(front, front - L * 0.5, x) * smoothstep(tail, tail + L, x);
        float fade = exp(-t / max(amzp_dropFade, 0.1) * 1.5);
        return sin(6.2831853 * (x - front) / L + radians(amzp_phase)) * w * fade * env;
    }
    void nmMain() {
        float2 W = layer;
        float2 c = float2(amzp_cx, 1.0 - amzp_cy);
        float2 p = (amzLayerNorm() - c) * W;
        float2 pa = float2(p.x, p.y * max(amzp_aspect, 0.1));
        float d = length(pa);
        float2 dir = d > 1e-4 ? float2(pa.x, pa.y / max(amzp_aspect, 0.1)) / d : float2(0.0);
        float e = 1.0;
        float h = wave(d);
        float dh = (wave(d + e) - wave(max(d - e, 0.0))) / (2.0 * e);
        float2 off = dir * dh * amzp_amp * max(amzp_wl, 2.0) / 6.2831853;
        float2 uv = amzLayerNorm() - off / W;
        float4 col = (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) ? float4(0.0) : amzTexture(0, l2s(uv));
        float la = radians(amzp_lAngle);
        float2 ld = float2(cos(la), sin(la));
        float sl = dot(dir, ld) * dh * max(amzp_wl, 2.0) / 6.2831853 * sign(amzp_amp) * min(abs(amzp_amp) / 20.0, 3.0);
        float hi = max(sl, 0.0) * amzp_light;
        float sh = max(-sl, 0.0) * amzp_shade;
        col.rgb = col.rgb * (1.0 - clamp(sh, 0.0, 1.0)) + amzp_lColor.rgb * col.a * hi;
        amzOutput = col;
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
